<script setup lang="ts">
import { formatCurrency } from "~~/shared/format";
import { calculateCartShipping } from "~~/shared/shipping";
const { lines, subtotal, update } = useCart();
const shipping = computed(() => lines.value.length ? calculateCartShipping(lines.value) : null);
useSeoMeta({ title: "Keranjang" });
</script>
<template><section class="container-shell py-12"><p class="eyebrow">Shopping bag</p><h1 class="section-title mt-3">Keranjang</h1><div v-if="!lines.length" class="surface mt-8 p-10 text-center"><p class="text-slate-500">Keranjangmu masih kosong.</p><NuxtLink to="/search" class="mt-5 inline-block font-black text-[#0b4697]">Lihat koleksi</NuxtLink></div><div v-else class="mt-8 grid gap-6 lg:grid-cols-[1fr_360px]"><div class="grid gap-3"><article v-for="line in lines" :key="line.variantId" class="surface flex gap-4 p-4"><img :src="line.image" :alt="line.name" class="h-24 w-24 rounded-xl object-cover"><div class="min-w-0 flex-1"><NuxtLink :to="`/products/${line.slug}`" class="font-black">{{ line.name }}</NuxtLink><p class="mt-1 text-xs text-slate-500">{{ line.sku }}</p><div class="mt-3 flex items-center justify-between"><input :value="line.quantity" type="number" min="0" :max="line.availableStock" class="field w-24" @input="update(line.variantId, Number(($event.target as HTMLInputElement).value))"><strong>{{ formatCurrency(line.unitPrice * line.quantity) }}</strong></div></div></article></div><aside class="surface h-fit p-6"><h2 class="text-xl font-black">Ringkasan</h2><dl class="mt-5 grid gap-3 text-sm"><div class="flex justify-between"><dt>Subtotal</dt><dd>{{ formatCurrency(subtotal) }}</dd></div><div class="flex justify-between"><dt>Estimasi ongkir</dt><dd>{{ shipping ? formatCurrency(shipping.chargedAmount) : '-' }}</dd></div></dl><NuxtLink to="/checkout" class="mt-6 block rounded-full bg-[#0b4697] px-5 py-3 text-center text-sm font-black text-white">Lanjut checkout</NuxtLink></aside></div></section></template>
